function legal(){const L=lang==='nl'?{title:'Juridische informatie',intro:'Juridische informatie en privacyverklaring van VK Automobile.',editor:'Website-uitgever',responsible:'Verantwoordelijke voor de website',responsibleText:'VK AUTOMOBILE SRL · Besloten vennootschap met beperkte aansprakelijkheid',id:'Ondernemingsgegevens',idp:'Ondernemingsnummer en btw-nummer: BE 0666.942.997.\nMaatschappelijke zetel: Rue des Franchimontois 39, 4820 Dison, België.\nVestiging en bezoekadres: Rue Mitoyenne 356, 4710 Lontzen, België.',contact:'Contact',privacy:'Privacy',privp:'De contact- en inruilformulieren bewaren geen gegevens op deze website. Bij verzending opent het mailprogramma van de bezoeker een vooraf ingevuld bericht naar VK Automobile. De bezoeker verzendt dit zelf. De gegevens worden daarna verwerkt in de mailbox van de ontvanger; bewaartermijnen worden door de onderneming bepaald. Voor vragen over uw gegevens of om uw rechten uit te oefenen, kunt u contact opnemen via het vermelde e-mailadres.',cookies:'Cookies en externe diensten',cookp:'Deze website gebruikt standaard geen analytics- of advertentiecookies. Google Fonts wordt extern geladen. Google Maps wordt pas geladen wanneer de bezoeker de kaart activeert. Externe links, waaronder AutoScout24 en Google Maps, vallen onder het privacybeleid van die diensten.',content:'Voertuigen en inhoud',contp:'Voertuiggegevens, prijzen, foto’s en beschikbaarheid worden per advertentie gepubliceerd en kunnen wijzigen. Neem contact op om de actuele beschikbaarheid en details te bevestigen. Garanties, verkoopvoorwaarden en eventuele bijkomende diensten worden in de concrete aanbieding en overeenkomst vermeld.'}:lang==='de'?{title:'Impressum',intro:'Rechtliche Informationen und Datenschutzhinweise der VK Automobile Website.',editor:'Website-Anbieter',responsible:'Verantwortlich für die Website',responsibleText:'VK AUTOMOBILE SRL · Gesellschaft mit beschränkter Haftung',id:'Unternehmensangaben',idp:'Unternehmens- und Umsatzsteuernummer: BE 0666.942.997.\nSitz: Rue des Franchimontois 39, 4820 Dison, Belgien.\nNiederlassung und Besucheradresse: Rue Mitoyenne 356, 4710 Lontzen, Belgien.',contact:'Kontakt',privacy:'Datenschutz',privp:'Die Kontakt- und Inzahlungnahmeformulare speichern keine Daten auf dieser Website. Beim Absenden öffnet sich das E-Mail-Programm des Besuchers mit einer vorbereiteten Nachricht an VK Automobile. Der Besucher sendet diese selbst. Anschließend werden die Daten im Postfach des Empfängers verarbeitet; die Aufbewahrungsdauer legt das Unternehmen fest. Für Fragen zu Ihren Daten oder zur Ausübung Ihrer Rechte kontaktieren Sie uns über die angegebene E-Mail-Adresse.',cookies:'Cookies und externe Dienste',cookp:'Diese Website verwendet standardmäßig keine Analyse- oder Werbe-Cookies. Google Fonts wird extern geladen. Google Maps wird erst geladen, wenn der Besucher die Karte aktiviert. Externe Links, darunter AutoScout24 und Google Maps, unterliegen den Datenschutzbestimmungen dieser Dienste.',content:'Fahrzeuge und Inhalte',contp:'Fahrzeugdaten, Preise, Fotos und Verfügbarkeit werden je Anzeige veröffentlicht und können sich ändern. Bitte kontaktieren Sie uns, um aktuelle Verfügbarkeit und Details zu bestätigen. Garantiebedingungen, Verkaufsbedingungen und zusätzliche Leistungen werden im konkreten Angebot und Vertrag angegeben.'}:{title:'Mentions légales',intro:'Informations légales et politique de confidentialité du site VK Automobile.',editor:'Éditeur du site',responsible:'Responsable du site',responsibleText:'VK AUTOMOBILE SRL · Société à responsabilité limitée',id:'Identification de l’entreprise',idp:'Numéro d’entreprise et TVA : BE 0666.942.997.\nSiège social : Rue des Franchimontois 39, 4820 Dison, Belgique.\nÉtablissement et adresse visiteurs : Rue Mitoyenne 356, 4710 Lontzen, Belgique.',contact:'Contact',privacy:'Confidentialité',privp:'Les formulaires de contact et de reprise ne stockent aucune donnée sur ce site. Lors de l’envoi, le logiciel de messagerie du visiteur s’ouvre avec un email prérempli à destination de VK Automobile ; le visiteur l’envoie lui-même. Les données sont ensuite traitées dans la boîte mail du destinataire, et leur durée de conservation est déterminée par l’entreprise. Pour toute question sur vos données ou pour exercer vos droits, contactez-nous à l’adresse email indiquée.',cookies:'Cookies et services externes',cookp:'Ce site n’intègre pas d’outil d’audience ou de cookies publicitaires par défaut. Google Fonts est chargé depuis un service externe. Google Maps n’est chargé que lorsque le visiteur active la carte. Les liens externes, notamment AutoScout24 et Google Maps, sont soumis aux politiques de confidentialité de ces services.',content:'Véhicules et contenus',contp:'Les caractéristiques, prix, photos et disponibilités des véhicules sont publiés par annonce et peuvent évoluer. Contactez VK Automobile pour confirmer les informations et la disponibilité actuelles. Les garanties, conditions de vente et prestations complémentaires sont indiquées dans l’offre et le contrat concernés.'};return pageHero(L.title,t.nav[4])+'<section class="section"><div class="wrap legal"><p>'+L.intro+'</p><h2>'+L.editor+'</h2><p>VK AUTOMOBILE SRL<br>'+L.responsibleText+'<br>+32 485 06 15 66<br>vkautimomobile@hotmail.com</p><h2>'+L.id+'</h2><p>'+L.idp.replace(/\\n/g,'<br>')+'</p><h2>'+L.responsible+'</h2><p>VK Automobile SRL</p><h2>'+L.contact+'</h2><p>Rue Mitoyenne 356, 4710 Lontzen, Belgique<br>vkautimomobile@hotmail.com</p><h2>'+L.privacy+'</h2><p>'+L.privp+'</p><h2>'+L.cookies+'</h2><p>'+L.cookp+'</p><h2>'+L.content+'</h2><p>'+L.contp+'</p></div></section>'}
const articles=[
{slug:'acheter-voiture-occasion',date:'2026-11-25',category:{fr:'Guide d’achat',nl:'Aankooptips',de:'Kaufberatung'},title:{fr:'Acheter une voiture d’occasion : les bonnes questions avant de décider',nl:'Een tweedehandswagen kopen: de juiste vragen vóór u beslist',de:'Gebrauchtwagen kaufen: die richtigen Fragen vor der Entscheidung'},excerpt:{fr:'Un guide pratique pour comparer les annonces, vérifier l’historique et préparer une visite sans se précipiter.',nl:'Een praktische gids om advertenties te vergelijken, de historiek te controleren en een bezoek goed voor te bereiden.',de:'Ein praktischer Leitfaden zum Vergleichen von Inseraten, Prüfen der Historie und Vorbereiten einer Besichtigung.'},body:{fr:[['Définissez votre usage avant le modèle','Commencez par vos trajets habituels, le nombre de passagers, le stationnement et votre budget global. Le prix d’achat ne représente qu’une partie du coût : prévoyez aussi assurance, taxe, carburant ou recharge, entretien et pneus.'],['Comparez des véhicules comparables','Comparez année, kilométrage, motorisation, finition et équipement. Une annonce très différente des autres mérite des questions précises plutôt qu’une conclusion immédiate.'],['Demandez les documents utiles','Demandez le carnet et les factures d’entretien disponibles, les informations de contrôle technique, les deux clés si elles sont annoncées, ainsi que les documents nécessaires à l’immatriculation. Les exigences peuvent varier selon le véhicule et la situation.'],['Prenez le temps de l’essai','Vérifiez à froid si possible, observez les voyants, écoutez les bruits inhabituels et testez les équipements. Si vous avez un doute, faites examiner le véhicule par un professionnel indépendant.'],['La prochaine étape','Préparez vos questions et contactez VK Automobile pour confirmer les informations d’une annonce et convenir d’une visite.']],nl:[['Bepaal eerst uw gebruik','Vertrek vanuit uw dagelijkse ritten, passagiers, parkeersituatie en totaalbudget. De aankoopprijs is slechts een deel: houd ook rekening met verzekering, belasting, brandstof of laden, onderhoud en banden.'],['Vergelijk gelijkwaardige wagens','Vergelijk bouwjaar, kilometerstand, motor, uitvoering en uitrusting. Een advertentie die sterk afwijkt, vraagt om gerichte vragen in plaats van snelle conclusies.'],['Vraag de documenten op','Vraag naar het onderhoudsboekje en beschikbare facturen, keuringsinformatie, eventuele tweede sleutel en documenten voor inschrijving. De vereisten kunnen per wagen en situatie verschillen.'],['Neem tijd voor de proefrit','Controleer indien mogelijk bij koude motor, let op waarschuwingslampjes en ongebruikelijke geluiden en test de uitrusting. Laat bij twijfel een onafhankelijke professional kijken.'],['Volgende stap','Bereid uw vragen voor en neem contact op met VK Automobile om advertentiegegevens te bevestigen en een bezoek af te spreken.']],de:[['Klären Sie zuerst Ihren Bedarf','Gehen Sie von Ihren täglichen Fahrten, Mitfahrern, Parkmöglichkeiten und dem Gesamtbudget aus. Der Kaufpreis ist nur ein Teil: Versicherung, Steuer, Kraftstoff oder Laden, Wartung und Reifen gehören ebenfalls dazu.'],['Vergleichen Sie ähnliche Fahrzeuge','Vergleichen Sie Baujahr, Kilometerstand, Motorisierung, Ausstattung und Ausführung. Deutliche Abweichungen sollten Sie gezielt hinterfragen.'],['Fragen Sie nach Unterlagen','Fragen Sie nach Wartungsheft und verfügbaren Rechnungen, Informationen zur technischen Prüfung, gegebenenfalls einem zweiten Schlüssel und den Zulassungsunterlagen. Anforderungen können je nach Fahrzeug und Situation variieren.'],['Nehmen Sie sich Zeit für die Probefahrt','Prüfen Sie wenn möglich bei kaltem Motor, achten Sie auf Warnleuchten und ungewöhnliche Geräusche und testen Sie die Ausstattung. Bei Unsicherheit kann ein unabhängiger Fachbetrieb das Fahrzeug prüfen.'],['Der nächste Schritt','Bereiten Sie Ihre Fragen vor und kontaktieren Sie VK Automobile, um Angaben zu einem Inserat zu bestätigen und einen Besichtigungstermin zu vereinbaren.']] }},
{slug:'reprise-voiture-preparer',date:'2026-11-25',category:{fr:'Reprise',nl:'Inruil',de:'Inzahlungnahme'},title:{fr:'Reprise de voiture : comment préparer une estimation utile',nl:'Auto inruilen: zo bereidt u een bruikbare waardebepaling voor',de:'Fahrzeug-Inzahlungnahme: So bereiten Sie eine aussagekräftige Bewertung vor'},excerpt:{fr:'Les informations et documents qui aident à étudier votre véhicule avec précision, sans promettre une valeur irréaliste.',nl:'Welke informatie en documenten helpen om uw wagen zorgvuldig te beoordelen, zonder een onrealistische prijs te beloven.',de:'Welche Angaben und Unterlagen helfen bei einer sorgfältigen Bewertung, ohne einen unrealistischen Preis zu versprechen.'},body:{fr:[['Rassemblez les informations exactes','Notez marque, modèle, version, première mise en circulation, kilométrage, motorisation et boîte. Le numéro de châssis peut être demandé lors d’un échange direct, mais évitez de le publier en ligne.'],['Préparez l’historique','Rassemblez les factures d’entretien, les informations sur les réparations, les sinistres connus et les contrôles techniques. La transparence facilite l’étude et évite les surprises lors de l’examen.'],['Présentez l’état honnêtement','Mentionnez les défauts, voyants, pneus, carrosserie et équipements manquants. Des photos nettes de l’extérieur, de l’intérieur et du compteur peuvent aider à préparer le rendez-vous.'],['Comprenez ce qu’est une estimation','Une valeur indicative n’est pas une offre ferme. L’évaluation finale dépend notamment de l’état réel, de l’historique, de la demande et de la vérification des documents.'],['Demandez votre étude','Envoyez les détails à VK Automobile via la page Reprise. Un interlocuteur pourra vous préciser les prochaines étapes.']],nl:[['Verzamel correcte gegevens','Noteer merk, model, uitvoering, eerste inschrijving, kilometerstand, motor en versnellingsbak. Het chassisnummer kan tijdens rechtstreeks contact worden gevraagd; publiceer het liever niet online.'],['Bereid de historiek voor','Verzamel onderhoudsfacturen, informatie over herstellingen, bekende schade en keuringen. Transparantie maakt de beoordeling eenvoudiger en voorkomt verrassingen.'],['Beschrijf de staat eerlijk','Vermeld gebreken, waarschuwingslampjes, banden, carrosserie en ontbrekende uitrusting. Duidelijke foto’s kunnen helpen om de afspraak voor te bereiden.'],['Begrijp een schatting','Een indicatieve waarde is geen bindend bod. De uiteindelijke beoordeling hangt onder meer af van de werkelijke staat, historiek, vraag en controle van documenten.'],['Vraag een beoordeling aan','Stuur uw gegevens via de pagina Inruil naar VK Automobile. Een medewerker kan de volgende stappen toelichten.']],de:[['Sammeln Sie genaue Angaben','Notieren Sie Marke, Modell, Ausführung, Erstzulassung, Kilometerstand, Motor und Getriebe. Die Fahrgestellnummer kann im direkten Kontakt benötigt werden; veröffentlichen Sie sie möglichst nicht online.'],['Bereiten Sie die Historie vor','Sammeln Sie Wartungsrechnungen, Angaben zu Reparaturen, bekannten Schäden und Prüfungen. Transparenz erleichtert die Bewertung und vermeidet Überraschungen.'],['Beschreiben Sie den Zustand ehrlich','Erwähnen Sie Mängel, Warnleuchten, Reifen, Karosserie und fehlende Ausstattung. Klare Fotos können den Termin vorbereiten.'],['Verstehen Sie eine Schätzung richtig','Ein Richtwert ist kein verbindliches Angebot. Der endgültige Wert hängt unter anderem vom tatsächlichen Zustand, der Historie, der Nachfrage und der Dokumentenprüfung ab.'],['Fordern Sie eine Bewertung an','Senden Sie Ihre Angaben über die Seite Inzahlungnahme an VK Automobile. Ein Ansprechpartner erläutert die nächsten Schritte.']] }},
{slug:'controle-voiture-occasion',date:'2026-11-25',category:{fr:'Conseils pratiques',nl:'Praktische tips',de:'Praxistipps'},title:{fr:'Visiter une voiture d’occasion : votre checklist simple',nl:'Een tweedehandswagen bekijken: een eenvoudige checklist',de:'Gebrauchtwagen besichtigen: Ihre einfache Checkliste'},excerpt:{fr:'Une liste à garder sur votre téléphone pour structurer la visite et ne pas oublier les points essentiels.',nl:'Een checklist voor op uw telefoon om het bezoek overzichtelijk te houden en belangrijke punten niet te vergeten.',de:'Eine Checkliste für Ihr Smartphone, damit Sie bei der Besichtigung die wichtigen Punkte im Blick behalten.'},body:{fr:[['Avant de partir','Confirmez le rendez-vous, l’adresse, la disponibilité et les documents annoncés. Vérifiez que vous pourrez voir le véhicule en lumière naturelle et effectuer un essai si autorisé.'],['À l’extérieur','Observez les écarts de teinte, l’alignement des panneaux, les traces de corrosion, l’état des pneus, les vitrages et les optiques. Ces observations sont des questions à approfondir, pas un diagnostic à elles seules.'],['À l’intérieur','Testez sièges, ceintures, climatisation, écran, vitres, éclairage et autres équipements annoncés. Regardez l’usure et comparez-la au kilométrage affiché.'],['Pendant l’essai','Écoutez les bruits, vérifiez le freinage et la direction dans des conditions sûres, surveillez les voyants et testez plusieurs types de routes si possible. Respectez toujours les consignes du vendeur.'],['Après la visite','Relisez les documents et les conditions écrites. En cas de doute technique, demandez un contrôle indépendant avant de vous engager.']],nl:[['Voor vertrek','Bevestig afspraak, adres, beschikbaarheid en aangekondigde documenten. Vraag of u de wagen bij daglicht kunt bekijken en indien toegestaan een proefrit kunt maken.'],['Buitenkant','Bekijk kleurverschillen, paneelnaden, corrosie, banden, ruiten en verlichting. Dit zijn aandachtspunten om verder te vragen, geen diagnose op zichzelf.'],['Interieur','Test stoelen, gordels, airco, scherm, ramen, verlichting en aangekondigde uitrusting. Vergelijk slijtage met de opgegeven kilometerstand.'],['Tijdens de proefrit','Let op geluiden, remmen en stuurgedrag in veilige omstandigheden, controleer waarschuwingslampjes en probeer indien mogelijk verschillende wegen. Volg altijd de instructies van de verkoper.'],['Na het bezoek','Lees documenten en schriftelijke voorwaarden opnieuw. Vraag bij technische twijfel een onafhankelijke controle vóór u beslist.']],de:[['Vor dem Termin','Bestätigen Sie Termin, Adresse, Verfügbarkeit und angekündigte Unterlagen. Fragen Sie, ob Sie das Fahrzeug bei Tageslicht ansehen und gegebenenfalls probefahren können.'],['Außen','Achten Sie auf Farbunterschiede, Spaltmaße, Korrosion, Reifen, Scheiben und Beleuchtung. Das sind Hinweise für Rückfragen, keine Diagnose für sich allein.'],['Innenraum','Testen Sie Sitze, Gurte, Klimaanlage, Display, Fenster, Beleuchtung und die angegebene Ausstattung. Vergleichen Sie den Verschleiß mit dem Kilometerstand.'],['Während der Probefahrt','Achten Sie unter sicheren Bedingungen auf Geräusche, Bremsen und Lenkung, beobachten Sie Warnleuchten und fahren Sie wenn möglich unterschiedliche Strecken. Befolgen Sie die Anweisungen des Verkäufers.'],['Nach der Besichtigung','Lesen Sie Unterlagen und schriftliche Bedingungen erneut. Lassen Sie bei technischen Zweifeln vor der Entscheidung eine unabhängige Prüfung durchführen.']] }}
];
function blog(){const intro=lang==='nl'?'Praktische informatie om met vertrouwen een wagen te kiezen, uw inruil voor te bereiden en uw bezoek te plannen.':lang==='de'?'Praktische Informationen für die Fahrzeugwahl, die Vorbereitung einer Inzahlungnahme und Ihren Besichtigungstermin.':'Des conseils pratiques pour choisir votre véhicule, préparer une reprise et organiser une visite en toute confiance.';return pageHero(lang==='nl'?'Autoadvies en nieuws':lang==='de'?'Auto-Ratgeber und Wissen':'Conseils automobiles',t.nav[5])+'<section class="section"><div class="wrap"><p class="intro">'+intro+'</p><div class="grid3 blog-grid">'+articles.map(a=>'<article class="card blog-card"><div class="card-image" style="background-image:url('+JSON.stringify(a.slug==='acheter-voiture-occasion'?'https://images.unsplash.com/photo-1492144534655-ae79c964c9d7?auto=format&fit=crop&w=1200&q=85':a.slug==='reprise-voiture-preparer'?'https://images.unsplash.com/photo-1489828334109-5d6d8b7b4a7e?auto=format&fit=crop&w=1200&q=85':'https://images.unsplash.com/photo-1503376780353-7e6692767b70?auto=format&fit=crop&w=1200&q=85')+')"></div><div class="card-body"><div class="meta"><span>'+a.category[lang]+'</span><span>'+a.date+'</span></div><h3>'+a.title[lang]+'</h3><p>'+a.excerpt[lang]+'</p><div class="card-foot"><a href="/blog/'+a.slug+'?lang='+lang+'">'+(lang==='nl'?'Lees artikel':lang==='de'?'Artikel lesen':'Lire l’article')+' ↗</a></div></div></article>').join('')+'</div><div class="conversion-panel"><h2>'+t.cta+'</h2><p>'+intro+'</p><div class="btnrow"><a class="btn" href="'+url('contact')+'">'+t.nav[4]+' ↗</a><a class="btn secondary" href="tel:+32485061566">+32 485 06 15 66</a></div></div></div></section>'}
function article(){const slug=params.get('slug')||location.pathname.split('/').filter(Boolean).pop();const a=articles.find(x=>x.slug===slug);if(!a)return pageHero(lang==='nl'?'Artikel niet gevonden':lang==='de'?'Artikel nicht gefunden':'Article introuvable',t.nav[5])+'<section class="section"><div class="wrap"><a class="btn secondary" href="/blog?lang='+lang+'">'+t.nav[5]+'</a></div></section>';const parts=a.body[lang];const reading=lang==='nl'?'Leestijd: 4 minuten':lang==='de'?'Lesezeit: 4 Minuten':'Lecture : 4 minutes';return '<section class="page-hero"><div class="wrap"><div class="breadcrumbs"><a href="/blog?lang='+lang+'">'+t.nav[5]+'</a> / '+a.category[lang]+'</div><div class="eyebrow">'+a.category[lang]+' · VK Automobile</div><h1>'+a.title[lang]+'</h1><p>'+a.excerpt[lang]+'</p><div class="notice">'+a.date+' · '+reading+'</div></div></section><article class="section"><div class="wrap legal article-body"><p class="intro">'+a.excerpt[lang]+'</p>'+parts.map((p,i)=>'<h2>'+(i+1)+'. '+p[0]+'</h2><p>'+p[1]+'</p>').join('')+'<div class="conversion-panel"><h2>'+t.cta+'</h2><p>'+(lang==='nl'?'Neem rechtstreeks contact op met VK Automobile voor actuele informatie of een afspraak.':lang==='de'?'Kontaktieren Sie VK Automobile direkt für aktuelle Informationen oder einen Termin.':'Contactez directement VK Automobile pour confirmer les informations ou convenir d’un rendez-vous.')+'</p><div class="btnrow"><a class="btn" href="tel:+32485061566">+32 485 06 15 66</a><a class="btn secondary" href="'+url('reprise')+'">'+t.nav[2]+'</a></div></div><p class="notice"><a href="/blog?lang='+lang+'">← '+t.nav[5]+'</a></p></div></article>'}
function detail(){return pageHero(t.detail,t.stock)+'<section class="section"><div class="wrap"><a href="'+url('stock')+'">← '+t.back+'</a><div id="vehicle-detail" class="empty" style="margin-top:25px">'+t.notFound+'</div></div></section>'}
const renderers={home,stock,trade,services,contact,legal,vehicle:detail,blog,article};$('#app').innerHTML=(renderers[page]||home)();
const contactMessage=lang==='nl'?'Hallo VK Automobile, ik heb een vraag over een voertuig of uw diensten.':lang==='de'?'Hallo VK Automobile, ich habe eine Frage zu einem Fahrzeug oder Ihren Leistungen.':'Bonjour VK Automobile, j’ai une question au sujet d’un véhicule ou de vos services.';
const rail=document.createElement('nav');rail.className='conversion-rail';rail.setAttribute('aria-label',lang==='nl'?'Direct contact':lang==='de'?'Direktkontakt':'Contact direct');rail.innerHTML='<a class="rail-call" href="tel:+32485061566">☎ '+(lang==='nl'?'Bel direct':lang==='de'?'Jetzt anrufen':'Appeler')+'</a><a class="rail-wa" href="https://wa.me/32485061566?text='+encodeURIComponent(contactMessage)+'" target="_blank" rel="noopener">WhatsApp ↗</a>';document.body.appendChild(rail);
