function card(v){return '<article class="card"><div class="card-image" style="background-image:url('+JSON.stringify((v.images&&v.images[0])||'https://images.unsplash.com/photo-1503376780353-7e6692767b70?auto=format&fit=crop&w=1000&q=80').replace(/\"/g,'&quot;')+')"><span class="label">'+(v.version||v.make||'VK')+'</span></div><div class="card-body"><div class="meta"><span>'+[v.year,v.fuel].filter(Boolean).join(' · ')+'</span><span>'+km(v.mileage)+'</span></div><h3>'+[v.make,v.model].filter(Boolean).join(' ')+'</h3><p>'+((v.description||'').slice(0,120))+'</p><div class="card-foot"><strong>'+money(v.price)+'</strong><a href="vehicle.html?id='+encodeURIComponent(v.id)+'&lang='+lang+'">'+t.ask+' ↗</a></div></div></article>'}
function setupForm(id,subject){const form=$(id);if(!form)return;form.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(form);let body=[...f.entries()].map(([k,v])=>k+': '+v).join('\n');location.href='mailto:vkautimomobile@hotmail.com?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body)})}
dataPromise.then(vehicles=>{const active=vehicles.filter(v=>v.published===true&&v.id&&v.make&&v.model);if(page==='home'){const target=$('#home-cars');if(target){target.innerHTML=active.slice(0,3).map(card).join('');if(!active.length)target.innerHTML='<div class="empty" style="grid-column:1/-1">'+t.empty+'<p><a class="btn secondary" href="https://vkautomobile.com/vehicles" target="_blank" rel="noopener">'+t.liveStock+' ↗</a></p></div>'}}if(page==='stock'){const ids=['make','fuel','gear'];const values=[...new Set(active.map(v=>v.make).filter(Boolean))];values.forEach(v=>$('#make').add(new Option(v,v)));[...new Set(active.map(v=>v.fuel).filter(Boolean))].forEach(v=>{const label=({fr:{Essence:'Essence',Diesel:'Diesel',Hybride:'Hybride',Électrique:'Électrique',LPG:'LPG'},nl:{Essence:'Benzine',Diesel:'Diesel',Hybride:'Hybride',Électrique:'Elektrisch',LPG:'LPG'},de:{Essence:'Benzin',Diesel:'Diesel',Hybride:'Hybrid',Électrique:'Elektro',LPG:'LPG'}}[lang][v]||v);$('#fuel').add(new Option(label,v))});[...new Set(active.map(v=>v.transmission).filter(Boolean))].forEach(v=>{const label=({fr:{Manuelle:'Manuelle',Automatique:'Automatique'},nl:{Manuelle:'Manueel',Automatique:'Automatisch'},de:{Manuelle:'Schaltgetriebe',Automatique:'Automatik'}}[lang][v]||v);$('#gear').add(new Option(label,v))});const run=()=>{const q=$('#q').value.trim().toLowerCase(),make=$('#make').value,fuel=$('#fuel').value,gear=$('#gear').value,max=$('#max').value===''?Infinity:Number($('#max').value);const filtered=active.filter(v=>([v.make,v.model,v.version].join(' ').toLowerCase().includes(q))&&(!make||v.make===make)&&(!fuel||v.fuel===fuel)&&(!gear||v.transmission===gear)&&(!Number.isFinite(max)||(v.price!=null&&v.price<=max)));$('#stock-results').innerHTML=filtered.map(card).join('');$('#stock-empty').classList.toggle('hidden',filtered.length>0);$('#count').textContent=filtered.length+' '+t.results};['q','make','fuel','gear','max'].forEach(id=>$('#'+id).addEventListener('input',run));$('#reset').addEventListener('click',()=>{['q','make','fuel','gear','max'].forEach(id=>$('#'+id).value='');run()});run()}if(page==='vehicle'){const id=params.get('id'),v=active.find(v=>v.id===id),box=$('#vehicle-detail');if(v)box.className='';if(v)box.innerHTML='<div class="split"><div class="split-photo" style="background-image:url('+JSON.stringify((v.images&&v.images[0])||'https://images.unsplash.com/photo-1503376780353-7e6692767b70?auto=format&fit=crop&w=1200&q=85').replace(/\"/g,'&quot;')+')"></div><div><div class="eyebrow">'+t.detail+'</div><h2>'+v.make+' '+v.model+'</h2><p>'+v.description+'</p><h3>'+money(v.price)+'</h3><ul class="checklist"><li>'+t.year+': '+(v.year||'—')+'</li><li>'+t.mileage+': '+km(v.mileage)+'</li><li>'+t.fuelLabel+': '+(v.fuel||'—')+'</li><li>'+t.gearLabel+': '+(v.transmission||'—')+'</li><li>'+t.body+': '+(v.body||'—')+'</li></ul><a class="btn" href="contact.html?lang='+lang+'">'+t.ask+' ↗</a></div></div>';}});setupForm('#trade-form',t.tradeSubject);setupForm('#contact-form',t.contactSubject);
